from pathlib import Path
import base64, hashlib, subprocess, zlib

path=Path("lib/main.dart")
expected_pre='4841cc7109ba2bf395735a9281925718f12928efdc8981dad9442aa1037a60e4'
expected_post='1040a4c877400a3d641ab54c4771ff50ef02be0a2afa626f6f607de79a3b1225'
actual=hashlib.sha256(path.read_bytes()).hexdigest()
if actual!=expected_pre:
    raise SystemExit(f"v320 baseline mismatch: expected {expected_pre}, got {actual}")

blob=''
patch=zlib.decompress(base64.b64decode(blob))
subprocess.run(["patch","--batch","--forward","--reject-file=-","-p0"],input=patch,check=True)
actual=hashlib.sha256(path.read_bytes()).hexdigest()
if actual!=expected_post:
    raise SystemExit(f"v320 output mismatch: expected {expected_post}, got {actual}")
body=path.read_text(encoding="utf-8")
for needle in [
    "bridgepoint-v320-resilience-market-guard-service-credit",
    "bridgepoint-v320-unsupported-market-preview",
    "bridgepoint-v320-owner-resilience-metrics",
    "bridgepoint_public_system_status_v320",
    "bridgepoint_user_market_context_v320",
    "bridgepoint_owner_resilience_metrics_v320",
    "BridgePoint is temporarily unavailable",
    "estimated restoration",
    "LIVE SOURCE OUTAGES",
    "AUTO-DISCOVERY PENDING",
]:
    if needle not in body:
        raise SystemExit(f"v320 release marker missing: {needle}")
print("BridgePoint v320 resilience + market guard patch applied and verified.")
